def sumDigits_imp : ℕ → ℕ :=
fun n =>
  (have total := 0;
    have current := n;
    do
    let r ←
      forIn Lean.Loop.mk ⟨current, total⟩ fun x r =>
          have current := r.fst;
          have total := r.snd;
          if current > 0 then
            have total := total + current % 10;
            have current := current / 10;
            do
            pure PUnit.unit
            pure (ForInStep.yield ⟨current, total⟩)
          else pure (ForInStep.done ⟨current, total⟩)
    match r with
      | ⟨current, total⟩ => pure total).run
